66	    CHAOSFPU::maybeCorrupt(o3::DynInst *dyn_inst)
67	    {
68	        if (!cpu || probability <= 0.0f) return false;
69	        if (max_faults != 0 && faults_injected_count >= max_faults) return false;
70	        if (!inWindow()) return false;
71	        OpClass oc = dyn_inst->opClass();
72	        if (!isFpOpClass(oc)) return false;
