/* sysreg_churn — v1.3 Phase 20 §21: MRS-read the whitelist system registers
 * in a loop (SCTLR_EL1/TTBR0_EL1/TCR_EL1/MAIR_EL1/VBAR_EL1/NZCV), so the
 * CHAOSArmSysReg injector's MRS-read-path hook has dense eligible events and
 * the corrupted value is IMMEDIATELY consumed (printed as checksum).
 * Static AArch64, no libc. */
#include <unistd.h>
#include <stdint.h>
#include <string.h>

static void put(const char *s){ write(1, s, strlen(s)); }
static void put_hex64(uint64_t v){
    char buf[16];
    for(int i=15;i>=0;--i){ unsigned x=v&0xf; buf[i]=x<10?'0'+x:'a'+x-10; v>>=4; }
    write(1,buf,16);
}

int main(void){
    uint64_t acc=0;
    for(long it=0; it<200000; it++){
        uint64_t v;
        asm volatile("mrs %0, sctlr_el1" : "=r"(v)); acc ^= v;
        asm volatile("mrs %0, ttbr0_el1" : "=r"(v)); acc ^= v*3;
        asm volatile("mrs %0, tcr_el1"   : "=r"(v)); acc ^= v*5;
        asm volatile("mrs %0, mair_el1"  : "=r"(v)); acc ^= v*7;
        asm volatile("mrs %0, vbar_el1"  : "=r"(v)); acc ^= v*11;
        asm volatile("mrs %0, nzcv"      : "=r"(v)); acc ^= v*13;
    }
    put("FINAL=");
    put_hex64(acc);
    put("\n");
    return 0;
}
EOF
